  ('blunznschdruudl', 'Blunznschdruudl', 'der', '', '', 'Wiener Küche & Gaumenfreuden', 'Blunzenstrudel', '[{"kategorie": "wörtlich", "text": "\"Blutwurststrudel\" (von [[Blunzen]]=\"Blutwurst\" und \"Strudel\"=\"Blätterteigstrudel\")"}, {"kategorie": "Kulinarik", "text": "\"Strudel mit Blunzenfüllung\" (herzhaftes, traditionell österreichisches Gericht, das seinen Ursprung in der ländlichen Schlachtküche hat: Ein kräftiger Teig – meist auf Basis von Kartoffelmehl oder Topfen – umhüllt eine deftige Füllung aus würziger Blutwurst (Blunze), gekochten Kartoffeln, gebratenen Zwiebeln und je nach Region auch Speck, Sauerkraut oder anderen Zutaten), \"Strudel von der Blunzen\", \"herzhafter Blutwurststrudel\""}]'::jsonb, 'A Blunznschdruudl is a echts Schmankal - aussn knusprig und innan healich wüazig!'),
  ('bock', 'Bock', 'der', '', '', 'Grundwortschatz Wienerisch', 'Bock', '[{"kategorie": "wörtlich", "text": "\"Bock\" (vom mittelhochdeutschen \"boc\"=\"Bock\")"}, {"kategorie": "zool.", "text": "\"männliches Tier von Schaf, Ziege, etc.\", Schafbock, Ziegenbock, Rehbock, Damhirschbock"}, {"kategorie": "techn.", "text": "sperriges Gestell, Rahmen, Rahmenwerk (Sägebock, etc.)"}, {"kategorie": "scherzhaft für", "text": "Motorrad, \"Bike\", [[Maurerbock]]"}, {"kategorie": "", "text": "Kutschersitz, Kutschbock (erhöhter Sitzplatz des Fiakers auf der Kutsche)"}, {"kategorie": "", "text": "\"Schuh\" bzw. \"Schuhe\" (abgeleitet vom \"Bocksleder\", aus dem die Schuhe gemacht sind)"}, {"kategorie": "Fußballerjargon", "text": "Stoppelschuh, Fußballschuh mit geschraubten Stollen, [[Schlapfen]]"}, {"kategorie": "", "text": "[[Bockbier]] (malziges Starkbier mit einem deutlich höheren Alkoholgehalt )"}, {"kategorie": "fig., von romani \"bokh\"=\"Hunger\"", "text": "Lust, Interesse, Anteilnahme"}, {"kategorie": "scherzhaft für", "text": "\"geiler Bock\", Liebhaber, [[Stecher]]"}]'::jsonb, 'Dea rennd umadum wiara brinftiga Bock auf Viagra!'),
  ('hammal', 'Hammal', 'das', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Hammerl', '[{"kategorie": "wörtlich", "text": "\"Hämmerchen\" (Verkleinerungsform von \"Hammer\", vom mittelhochdeutschen \"hamer\"=\"Hammer\")"}, {"kategorie": "allg.", "text": "\"festes Schuhwerk\" (=besonders stabile oder grobe Schuhe, die beim Auftreten laut hörbar \"auf den Boden hämmern\"), fester Halbschuh, \"robuster Treter\", \"fester [[Bock]]\""}, {"kategorie": "Sport", "text": "Wanderschuh, Bergschuh, Trekking-Schuh"}, {"kategorie": "Fußballerjargon", "text": "Fußballschuh, Stollenschuh, \"Kickerstiefel\", \"Treter\" ([[Mit]] de neichn Hammaln schiassda wiara junga Gott - drei Tiarln in an Schbüü!\")"}, {"kategorie": "Mechanikerjargon", "text": "Reifen, Autoreifen, Fahrzeugreifen, \"Pneu\""}]'::jsonb, 'Dea hod si neiche Hammaln aufzoong - braade Dinga, peafekt fian Drift!'),
