  ('foeoedweewae', 'Föödweewä', 'der', '', '', 'Wiener Wörter mit schillernder Geschichte', 'Feldwebel', '[{"kategorie": "wörtlich", "text": "\"Feldwebel\" (ursprünglich \"Feldweibel\", Determinativkompositum aus \"Feld\"=\"Gefechtsfeld\" und \"Weibel\"=\"Amtsdiener\")"}, {"kategorie": "mil.", "text": "historischer Unteroffiziersrang, Oberfeldwebel, Unterfeldwebel"}, {"kategorie": "scherzhaft für", "text": "\"große Schaumkrone auf einem Bier\", Schaumkrone, Bierkrone"}, {"kategorie": "in Bezug auf Frauen", "text": "\"resolut auftretende Frau\", \"eiserne Lady\", \"Herrin im Haus\""}]'::jsonb, 'I hob an Föödweewä dahaam - waunn de pfeifd, schdee I schdraumm!'),
